#!/bin/bash
# Rebuild the trainer programs from their ASCII sources and test disks with them added.
#   sources: src/cheats/TRAINER.ASC (interactive trainer) and src/cheats/LISTSAVE.ASC (list the saves on a disk; generated by tools/mk_listsave.py)
#            (CRLF lines, end with Ctrl-Z); TRUMBLE.ASC (listen to the Trumble squeak and the other effects with BASIC SOUND); EDITSAVE.ASC is generated by tools/mk_editsave.py
#   output : src/cheats/<NAME>.BAS (AMSDOS header) and .BAS.txt (listing)
#            work/firebird_cheat.dsk  (copy of the Firebird disk plus both programs)
#            work/missions_cheat.dsk  (the combined mission build plus the save editor and viewer, when work/elite_missions.dsk exists)
# The CPC's own BASIC does the tokenising (cpcxray headless), so the result is a real tokenised file.
set -e
cd "$(dirname "$0")/.."
export PATH="$HOME/.local/bin:$PATH"
D=src/cheats
# add FILES to DISK with dskx (tools/add_files.py): iDSK may fill the odd-sector tracks, which AMSDOS cannot read ("Drive A: read fail"); a file of the same name is replaced
add_files() { python3 -I tools/add_files.py "$@" >/dev/null; }
DISK=Elite_UK_Firebird_cracked_trainer.dsk
PROGS="TRAINER CHEATB EDITSAVE LISTSAVE TRUMBLE"
# TRUMBLE.BAS is built into src/cheats/ but not put on the disks (the squeak is settled); the disks get TRAINER, EDITSAVE (and LISTSAVE on some)
for P in $PROGS; do
  rm -f work/tmp_asc.dsk work/xray/disk/tmp_asc.dsk work/xray/disk/tmp_tok.dsk
  iDSK work/tmp_asc.dsk -n >/dev/null 2>&1
  iDSK work/tmp_asc.dsk -i $D/$P.ASC -t 0 >/dev/null 2>&1
  cp work/tmp_asc.dsk work/xray/disk/tmp_asc.dsk
  (cd work/xray && PROG=$P ~/.local/share/uv/tools/cpcxray/bin/python -I ../../tools/cheat_tokenise.py)
  rm -rf work/tmp_tok; mkdir work/tmp_tok
  python3 -I tools/dskx.py work/xray/disk/tmp_tok.dsk work/tmp_tok >/dev/null
  cp work/tmp_tok/$P.BAS.raw $D/$P.BAS
  python3 -I tools/bastok.py $D/$P.BAS --header > $D/$P.BAS.txt
  echo "built $D/$P.BAS ($(wc -c < $D/$P.BAS) bytes with header)"
done
cp $DISK work/firebird_cheat.dsk
cp $D/CHEATB.BAS work/CHEATB.BIN
add_files work/firebird_cheat.dsk -CHEAT.BAS $D/TRAINER.BAS $D/EDITSAVE.BAS work/CHEATB.BIN
python3 -I tools/hide_files.py work/firebird_cheat.dsk
cp work/firebird_cheat.dsk work/xray/disk/firebird_cheat.dsk
# the mission build is rebuilt every time: a leftover work/elite_missions.dsk could hold an older game than src/
python3 -I tools/build_dsk.py --missions >/dev/null   # a failed build stops the script (set -e); build_dsk.py puts our TRAINER.BAS and CHEATB.BIN on the disk (and removes Firebird's CHEAT.BAS)
cp work/elite_missions.dsk work/missions_cheat.dsk
add_files work/missions_cheat.dsk $D/EDITSAVE.BAS $D/LISTSAVE.BAS
python3 -I tools/hide_files.py work/missions_cheat.dsk
cp work/missions_cheat.dsk work/xray/disk/missions_cheat.dsk
echo "also built work/missions_cheat.dsk (mission build + trainer + save viewer)"
rm -rf work/tmp_asc.dsk work/tmp_tok work/xray/disk/tmp_asc.dsk work/xray/disk/tmp_tok.dsk
# the same TRAINER.BAS detects the build, so it also goes onto copies of the German and French disks
for V in "de Elite_DE_cracked.dsk" "fr Elite (1985)(Firebird Software)(fr).dsk"; do
  L=${V%% *}; SRCD=${V#* }
  cp "$SRCD" work/${L}_cheat.dsk
  add_files work/${L}_cheat.dsk -CHEAT.BAS $D/TRAINER.BAS $D/EDITSAVE.BAS work/CHEATB.BIN
  python3 -I tools/hide_files.py work/${L}_cheat.dsk
  cp work/${L}_cheat.dsk work/xray/disk/${L}_cheat.dsk
  echo "also built work/${L}_cheat.dsk (trainer + save viewer and editor)"
done
# one German disk with everything: the game, the trainer, the save tools and the four commander saves of Elite_DE_savegames.dsk
# (work/de_cheat.dsk plus the saves and LISTSAVE). The saves stay visible (no hide_files after adding them): LISTSAVE finds
# them through CAT, which does not show System files, and the game's save/load lists them too.
cp work/de_cheat.dsk work/de_savegames.dsk
rm -rf work/de_saves_tmp; mkdir work/de_saves_tmp work/de_saves_tmp/raw
python3 -I tools/dskx.py Elite_DE_savegames.dsk work/de_saves_tmp >/dev/null
for F in work/de_saves_tmp/*.raw; do cp "$F" "work/de_saves_tmp/raw/$(basename "${F%.raw}")"; done
add_files work/de_savegames.dsk work/de_saves_tmp/raw/* $D/LISTSAVE.BAS
rm -rf work/de_saves_tmp
cp work/de_savegames.dsk work/xray/disk/de_savegames.dsk
echo "also built work/de_savegames.dsk (German game + trainer + save tools + the four saves, visible)"
echo "built work/firebird_cheat.dsk"
